   224→{
   225→    const struct uart_bk7258_config *cfg = dev->config;
   226→    int ret;
   227→    if (cfg->clk_dev != NULL) {
   228→        ret = clock_control_on(cfg->clk_dev, cfg->clk_id);
   229→        if (ret != 0) {
