   231→        }
   232→    }
   233→    ret = pinctrl_configure_pins(uart1_d1_pins,
   234→                                ARRAY_SIZE(uart1_d1_pins),
   235→                                PINCTRL_REG_NONE);
   236→    if (ret != 0) {
   237→            return ret;
   238→    }
   239→    uint32_t val;
   240→    uint32_t clk_div = BK7258_UART_XTAL_FREQ / cfg->current_speed - 1;
   241→
   242→    /* 打开 RX enable：UART_CFG bit1。
   243→    * 不动 soc_reset_hook 的早期初始化，
   244→    * 只在这里补充 driver init 时打开 RX。 */
