   246→        | (3U << 3)   /* data bits = 8-bit */
   247→        | BIT(1)      /* rx enable */
   248→        | BIT(0);     /* tx enable */
   249→
   250→    sys_write32(val, cfg->base + BK7258_UART_CFG_OFFSET);
   251→#ifdef CONFIG_UART_INTERRUPT_DRIVEN
   252→    val = sys_read32(BK7258_SYS_CPU0_INT_0_31_EN);
   253→    val |= BK7258_SYS_CPU0_UART1_GATE;
   254→    sys_write32(val, BK7258_SYS_CPU0_INT_0_31_EN);
   255→    val = sys_read32(cfg->base + BK7258_UART_FIFO_THRESHOLD_OFFSET);
   256→    val &= ~BK7258_UART_RX_FIFO_THRESHOLD_MASK;
   257→    val |= BK7258_UART_RX_FIFO_THRESHOLD << BK7258_UART_RX_FIFO_THRESHOLD_SHIFT;
   258→    sys_write32(val, cfg->base + BK7258_UART_FIFO_THRESHOLD_OFFSET);
   259→    cfg->irq_config_func(dev);
   260→#endif
   261→    return 0;
   262→}
