    64→     * 这两块在物理地址上紧邻，可以合并成一块。 */
    65→    sram0: memory@28000000 {
    66→        compatible = "mmio-sram";
    67→        reg = <0x28000000 0x00020000>;    /* 128 KB */
    68→    };
